def convert_to_nimionese(word):
    # Replace 'Each' with 'Dach'
    if word == "Each":
        return "Dach"

    # Define the mapping for hard consonants
    consonant_map = {
        'b': 'g', 'c': 'd', 'd': 'f', 'g': 'k', 'k': 'm',
        'n': 'p', 'p': 'r', 't': 'v'
    }

    # Convert the first letter to its corresponding hard consonant
    if word[0].lower() in consonant_map:
        word = consonant_map[word[0].lower()] + word[1:]

    # Process subsequent hard consonants
    result = []
    for i, char in enumerate(word):
        if char.lower() in consonant_map:
            if i > 0:
                result.append(consonant_map[char.lower()])
            else:
                result.append(char)
        else:
            result.append(char)

    # Add 'ah', 'oh', or 'uh' at the end if the word ends with a hard consonant
    last_consonant = None
    for char in reversed(result):
        if char.lower() in consonant_map:
            last_consonant = char.lower()
            break

    if last_consonant:
        if last_consonant in 'aeiou':
            ending = ''
        elif last_consonant == 'y':
            ending = 'ah'
        else:
            ending = 'u' if ord(last_consonant) > ord('a') + 2 else 'o'

        result.append(ending)

    return ''.join(result).replace('-', '')

